head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > chooseOption]<br/>AutoComplete 컴포넌트에 '선택 안내'를 의미하는 아이템을 추가할지 설정합니다.",
    "validation" : [
        "noResult='clear' 이거나 emptyItem='true' 일때 검색 결과가 없는 값을 입력하고 편집을 완료하면 '선택 안내' 아이템이 선택됩니다.",
    ]
}

// 사용자가 입력한 값
scwin.gVar = { "typedValue" : "" };



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="dlt_city">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_city.setJSON([
        { "label" : "Incheon", "value" : "3" },
        { "label" : "Seoul", "value" : "1" },
        { "label" : "Busan", "value" : "4" },
        { "label" : "Sejong", "value" : "2" }
    ]);

    // con_chooseOption 기본값 true, con_noResult 기본값 clear
    con_chooseOption.setValue("2");
    con_noResult.setValue("clear");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(DataList 순서) : Incheon(3) / Seoul(1) / Busan(4) / Sejong(2)\n- 생성 후 Seoul 을 선택해 둔 상태\n[절차] 결과창 clear -> 대상 클릭 -> 아이템에 없는 값(Tokyo) 입력 -> 선택 아이템 확인 (버튼을 누르면 포커스가 해제되어 편집이 끝난다)"', '', 'label1');

    scwin.gVar.typedValue = "";

    // gdl_boolean 은 getText 로 읽는다 (미설정은 createCList 가 속성에서 제외)
    let properties = {
        chooseOption : con_chooseOption.getText(),
        noResult : con_noResult.getValue(),
        emptyItem : con_emptyItem.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());

    // 편집 완료 전 선택 아이템을 일반 아이템(Seoul)으로 둔다 (이전 선택 유지와 선택 안내 아이템 선택을 구분)
    target1.setValue("1");

    // 편집이 끝나면 입력창의 표시값이 선택된 아이템으로 바뀌므로 사용자가 입력한 값을 따로 기록
    document.querySelector("input[id='" + target1.id + "_input']").addEventListener("input", function (e) {
        scwin.gVar.typedValue = e.target.value;
    });
}



// 편집 완료 후 선택된 아이템 출력 (validation 1)
scwin.btn_getSelectedInfo_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 : " + scwin.gVar.typedValue + " -> 선택된 아이템(인덱스 / Label / Value) : " + target1.getSelectedIndex() + " / " + target1.getText() + " / " + target1.getValue());
};
